package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for ReferenceType.buildCanonicalName().
 * Since buildCanonicalName is protected, we use reflection to access it.
 */
public class ReferenceType_buildCanonicalName_TriageGen1Test {

    @Test
    public void testBuildCanonicalName() throws Exception {
        // Setup dependencies
        Class<?> clazz = String.class;

        // Mock JavaType for _referencedType
        JavaType mockReferencedType = mock(JavaType.class);
        when(mockReferencedType.toCanonical()).thenReturn("java.lang.String");

        // Use the public construct method to create an instance
        // ReferenceType.construct(Class<?> cls, JavaType refType) is available
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType);

        // Access the protected method buildCanonicalName via reflection
        Method method = ReferenceType.class.getDeclaredMethod("buildCanonicalName");
        method.setAccessible(true);

        // Execute
        String result = (String) method.invoke(referenceType);

        // Verify
        // Expected format: _class.getName() + '<' + _referencedType.toCanonical()
        String expected = "java.lang.String<java.lang.String";
        assertEquals(expected, result);
    }

    @Test
    public void testBuildCanonicalNameWithDifferentTypes() throws Exception {
        // Setup dependencies
        Class<?> clazz = Integer.class;

        // Mock JavaType for _referencedType
        JavaType mockReferencedType = mock(JavaType.class);
        when(mockReferencedType.toCanonical()).thenReturn("int");

        // Create instance
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType);

        // Access the protected method
        Method method = ReferenceType.class.getDeclaredMethod("buildCanonicalName");
        method.setAccessible(true);

        // Execute
        String result = (String) method.invoke(referenceType);

        // Verify
        String expected = "java.lang.Integer<int";
        assertEquals(expected, result);
    }

    @Test
    public void testBuildCanonicalNameWithComplexType() throws Exception {
        // Setup dependencies
        Class<?> clazz = java.util.List.class;

        // Mock JavaType for _referencedType
        JavaType mockReferencedType = mock(JavaType.class);
        // Simulate a complex canonical name returned by the referenced type
        when(mockReferencedType.toCanonical()).thenReturn("java.util.Map<java.lang.String, java.lang.Integer>");

        // Create instance
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType);

        // Access the protected method
        Method method = ReferenceType.class.getDeclaredMethod("buildCanonicalName");
        method.setAccessible(true);

        // Execute
        String result = (String) method.invoke(referenceType);

        // Verify
        String expected = "java.util.List<java.util.Map<java.lang.String, java.lang.Integer>";
        assertEquals(expected, result);
    }
}
